sections.example:
from security_lab import read_document
try:
    read_document(None,'a')
except PermissionError:
    pass
else:
    raise AssertionError('anonymous read allowed')

from security_lab import parse_update
assert parse_update({'title':' Notes '}) == {'title':'Notes'}
# {'title':'Notes','owner':'alice'} is rejected, not mass-assigned.

from security_lab import safe_audit
assert safe_audit('document.read','u-123','denied') == {'event':'document.read','subject':'u-123','outcome':'denied'}
# The subject is an internal ID, never a password/token/body.
